// Presentation clocks use exported native durations. Native cooldown starts at activation.
function skillClock(timer,now){
 if(!timer)return {phase:'ready',progress:1,remaining:0};
 if(now<timer.activeUntil)return {phase:'active',progress:Math.max(0,(timer.activeUntil-now)/(timer.activeUntil-timer.startedAt)),remaining:(timer.activeUntil-now)/1000};
 if(now<timer.readyAt)return {phase:'cooldown',progress:Math.max(0,Math.min(1,(now-timer.activeUntil)/(timer.readyAt-timer.activeUntil))),remaining:(timer.readyAt-now)/1000};
 return {phase:'ready',progress:1,remaining:0};
}
function skillPresentation(i,now=performance.now()){
 if(!skillOwned(i))return {phase:'locked',progress:0,remaining:0};
 const s=fx().skills[i];
 if(state.condition==='active'&&i!==2)return {phase:'active',progress:.75,remaining:s.duration*.75};
 if(['active','cooldown'].includes(state.condition))return {phase:'cooldown',progress:.35,remaining:s.cooldown*.65};
 return skillClock(state.skillTimers[i],now);
}
const skillState=i=>skillPresentation(i).phase;
function skillTime(seconds){const whole=Math.max(0,Math.ceil(seconds));return String(Math.floor(whole/60)).padStart(2,'0')+':'+String(whole%60).padStart(2,'0');}
function skillStatus(view){return view.phase==='active'?'ACTIVE · '+skillTime(view.remaining):view.phase==='cooldown'?'WAIT · '+skillTime(view.remaining):view.phase==='locked'?'LOCKED':'READY';}
function skillRing(view){return '<svg class="skill-ring" viewBox="0 0 64 64" aria-hidden="true"><circle class="skill-ring-track" cx="32" cy="32" r="29"/><circle class="skill-ring-progress" cx="32" cy="32" r="29" pathLength="100" stroke-dasharray="'+(view.progress*100).toFixed(3)+' 100" transform="rotate(-90 32 32)"/></svg>';}
function tickSkills(){
 const views=skillNames.map((_,i)=>skillPresentation(i));window.classicProgressFeel?.skills(views);
 if(views.some((v,i)=>v.phase!==state.skillStates[i])){state.skillStates=views.map(v=>v.phase);refresh();return;}
 document.querySelectorAll('#scroll-Home .classic-skill').forEach((button,i)=>{const view=views[i],ring=button.querySelector('.skill-ring-progress'),label=button.querySelector('.skill-status');if(ring)ring.setAttribute('stroke-dasharray',(view.progress*100).toFixed(3)+' 100');if(label&&label.textContent!==skillStatus(view))label.textContent=skillStatus(view);});
 document.querySelectorAll('.skill-quick-row').forEach(row=>{const i=Number(row.dataset.skillIndex),view=views[i],ring=row.querySelector('.skill-ring-progress'),label=row.querySelector('.skill-status');row.dataset.state=view.phase;ring.setAttribute('stroke-dasharray',(view.progress*100).toFixed(3)+' 100');if(label.textContent!==skillStatus(view))label.textContent=skillStatus(view);});
 document.querySelectorAll('[data-skill-hero]').forEach(hero=>{const i=Number(hero.dataset.skillHero),view=views[i],ring=hero.querySelector('.skill-ring-progress'),status=hero.querySelector('.skill-hero-status'),button=hero.closest('.modal-layer').querySelector('.skill-hero-activate');hero.dataset.state=view.phase;ring.setAttribute('stroke-dasharray',(view.progress*100).toFixed(3)+' 100');if(status.textContent!==skillStatus(view))status.textContent=skillStatus(view);if(button&&button.textContent!==skillHeroAction(i,view))button.textContent=skillHeroAction(i,view);});
}
