const homeNormal=()=>skillState(0)==='active'?fx().boostedNormal:displayNormal();
const homeTap=()=>skillState(0)==='active'?fx().boostedTap:displayTap();
const rateAmount=(amount,unit)=>money(amount)+'<span class="income-unit">/'+unit+'</span>';
function totalEarnings(now=performance.now()){
 recentTapEarnings=recentTapEarnings.filter(t=>now-t.at<1000);
 return homeNormal().value+recentTapEarnings.reduce((sum,t)=>sum+t.value,0);
}
function updateTotalEarnings(){const value=$('home-total-rate');if(!value)return;const next=rateAmount(totalEarnings(),'sec');if(value.innerHTML!==next)value.innerHTML=next;}
function earningsIcon(){return '<svg class="game-icon earnings-icon" data-icon="earnings" viewBox="0 0 23.8 21.56" aria-hidden="true"><path d="M0 15.092h5.474v6.468H0zm7.378-5.39h5.474V21.56H7.378zm7.378-5.39h5.474V21.56h-5.474z" fill="#e6a11d"/></svg>';}
function home(){
 const f=fx(),fresh=state.levels[0]===0,goal=state.pin?D.upgrades.find(u=>u.id===state.pin):null;
 return `<div class="home-next">${b('Navigate',fresh?'Products:first':goal?'Player':'Products',`${icon(fresh?'shelf':'burst')}<span class="home-next-copy"><small>NEXT DISPLAY</small><strong>${fresh?'Stock Phuljhari · '+cash(f.levelQuotes['0']['1'].cost):goal?esc(goal.name):'Phuljhari · discover your next signature'}</strong></span>`,'home-next-action')}${b('Tip','product-levels','<span aria-hidden="true">?</span>','home-next-help').replace('class="home-next-help"','class="home-next-help" aria-label="Next display guidance"')}</div>`+
 `<div class="classic-income"><div class="income-breakdown"><div class="automatic-income"><small>AUTOMATIC SALES</small><strong>${rateAmount(homeNormal().value,'sec')}</strong></div><div class="tap-income"><small>PER TAP</small><strong>${rateAmount(homeTap().value,'tap')}</strong></div></div><div class="total-income"><span class="income-total-heading">${earningsIcon()}<small>EARNING NOW</small></span><strong id="home-total-rate">${rateAmount(totalEarnings(),'sec')}</strong></div></div>`+
 `<div class="classic-skills">${skillNames.map((n,i)=>{const view=skillPresentation(i),s=view.phase;return b('ActivateSkill',i,`<span class="skill-disc">${icon(s==='locked'?'lock':['burst','hands','order'][i])}${skillRing(view)}</span><strong>${n}</strong><small class="skill-status">${skillStatus(view)}</small>`,'classic-skill',s!=='ready'||blocked()).replace('class="classic-skill"',`class="classic-skill" data-state="${s}"`);}).join('')}</div>`;
}
function levelQuote(i){const level=i<0?fx().tapLevel:state.levels[i],quantity=level===0?'1':state.quantities[i<0?'tap':'products'];const q=fx().levelQuotes[i][quantity];return quantity==='Max'&&q.count===0&&level<100000?{...fx().levelQuotes[i]['1'],affordable:false}:q;}
const milestoneReward=level=>level<=25?2:level===50?3:level===100?4:5;
function player(){const f=fx(),q=levelQuote(-1);return `<div class="classic-toolbar">${b('Navigate','Statistics',icon('stats')+'Stats','player-icon')}${b('Navigate','Skills',icon('skills')+'Skills','player-icon')}${b('Navigate','Achievements',icon('prestige')+'Achievements','player-icon achievement-tab')}${b('Quantity','tap:cycle','Buy '+(state.quantities.tap==='Max'?'Max':'×'+state.quantities.tap))}</div>`+
row(`Salesmanship · Level ${f.tapLevel}`,cash(f.tap)+' per tap',b('BuyLevels',-1,cash(q.cost)+'<small>Buy ×'+Math.max(1,q.count)+'</small>','action row-action',!q.affordable||state.levelBought.has(-1)||funds()===0||blocked()),`<span class="row-art">${icon('player')}</span>`)+
row('A brighter beginning',f.fame+' Fame · products ×'+num(f.multiplier)+' · taps ×'+num(f.tapMultiplier),b('Navigate','Prestige','View prestige','action row-action'),`<span class="row-art">${icon('prestige')}</span>`)+
section('Upgrades',D.upgrades.filter(u=>owned(u.id)).length+' / '+D.upgrades.length)+b('BuyAllUpgrades','','Buy all Upgrades','action buy-all',blocked()||funds()===0||!f.batches.All.ids.some(id=>!owned(id)))+sampleRows();}

function productMilestone(level){const previous=level<10?0:level<25?10:level<50?25:level<100?50:Math.floor(level/100)*100,next=level>=100000?0:level<10?10:level<25?25:level<50?50:(Math.floor(level/100)+1)*100;return {previous,next,percent:next?Math.max(0,Math.min(100,(level-previous)/(next-previous)*100)):100};}
function products(){return `<div class="classic-toolbar"><strong>Automatic sales · ${cash(displayNormal())}/s</strong>${b('Quantity','products:cycle','Buy '+(state.quantities.products==='Max'?'Max':'×'+state.quantities.products))}</div>`+D.products.map((x,i)=>{const q=levelQuote(i),available=i===0||state.levels[i-1]>0,level=state.levels[i],m=productMilestone(level);return `<article class="sheet-row product-row">${b('Navigate','ProductDetail:'+i,`<span class="product-image-frame">${art(i)}<span class="product-milestone-bar" role="progressbar" aria-label="${esc(x.name)} milestone progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${m.percent}" aria-valuetext="Level ${level}; ${Math.round(m.percent)}% from level ${m.previous} to ${m.next}" title="Level ${level} · ${m.previous} → ${m.next}"><span style="width:${m.percent}%"></span></span></span><span class="product-tile-copy"><span class="product-tile-name">${esc(x.name)}</span><span class="product-tile-income">${cash(q.productBefore)}/s</span></span>`,'details-link').replace('class="details-link"',`class="details-link" aria-label="View ${esc(x.name)} details"`)}<span class="product-tile-level">Lvl : ${level}</span>${b('BuyLevels',i,cash(q.cost)+`<small>${!available?'Own '+D.products[i-1].name:state.levelBought.has(i)?'Previewed':state.levels[i]===0?'Stock shelf':'Upgrade ×'+q.count}</small>`,'action row-action',!available||!q.affordable||state.levelBought.has(i)||funds()===0||blocked())}</article>`;}).join('');}
function legacy(){return talent();}
function shop(){
 // Reserve the retired shortcut slots so pack and contextual-tip IDs stay stable.
 serial++;
 const packs=D.packs.map((x,i)=>row(esc(x.name),`${x.kajuKatli} KK<br>${x.kajuKatli/100} Talent draws`,b('Purchase',i,'Unavailable','action row-action',true),'<span class="row-art currency-pack-art">'+window.classicCurrency.icon({decorative:true})+'</span>').replace('class="sheet-row"','class="sheet-row pack"')).join('');
 serial++;
 return `<div class="shop-balance"><div><small>KAJU KATLI</small><br><strong>${state.kk} KK</strong></div></div><div class="native-store-status">Kaju Katli packs are not available yet.</div>`+packs;
}

function renderPanels(){const focused=focusIdentity();const render={Home:home,Player:player,Products:products,Legacy:legacy,Shop:shop};for(const n of tabs){scope=n;serial=0;const e=$('scroll-'+n),y=e.scrollTop;e.innerHTML=render[n]();nativePanelGuide(n);e.scrollTop=y;}$('legacy-kk').textContent=state.kk+' KK';$('legacy-kk').setAttribute('aria-label','Current Kaju Katli balance: '+state.kk);const f=fx();$('cash-value').textContent=state.condition==='insufficient'?'₹0':cash(f.cash);const sign=document.querySelector('.shop-title');sign.textContent=state.name;sign.title=state.name;sign.setAttribute('aria-label','Shop name: '+state.name);D.products.forEach((p,i)=>{const slot=$('display-'+p.id);slot.dataset.owned=String(state.levels[i]>0);slot.querySelector('.product-art').innerHTML=art(i);});$('app').dataset.reducedMotion=String(state.settings.motion);$('app').dataset.sound=String(state.settings.sound);$('app').dataset.music=String(state.settings.music);window.classicAudio?.configure({sound:state.settings.sound,music:state.settings.music});nativeDecorations();window.classicProgressFeel?.skills(skillNames.map((_,i)=>skillPresentation(i)));window.classicCurrency.decorate($('app-inner'));updateNativeNotifications();syncContract();restoreFocus(focused);requestAnimationFrame(updateScrollCues);}
function updateNativeNotifications(){
 const ready=window.classicAchievements.readyCount(state,fx(),D)>0;
 const available=D.upgrades.some(u=>eligible(u)&&fx().upgrades[u.id].price.value<=funds());
 $('nav-Player').classList.toggle('has-notification',ready||available);
 $('nav-Legacy').classList.toggle('has-notification',!locked()&&(state.credits>0||!!state.reveal));
 document.querySelector('.achievement-tab')?.classList.toggle('has-notification',ready);
}

const category=u=>[0,1,10,11].includes(u.effect)?'Products':[2,3,4].includes(u.effect)?'Tapping':[7,8,9].includes(u.effect)?'Skills':'Shop';
function effect(u){const p=D.products[u.target]?.name||'product';switch(u.effect){case 0:return '×'+u.factor+' '+p+' income';case 1:return 'Product level prices ×'+u.factor;case 2:return '×'+u.factor+' direct tap income';case 3:return 'Link normal shop sales to tapping';case 4:return 'Tap training prices ×'+u.factor;case 5:return '×'+u.factor+' normal shop income';case 6:return 'Cash upgrade prices ×'+u.factor;case 7:return (u.rank===1?'Unlock ':'Improve ')+skillNames[u.target];case 8:return 'Longer '+skillNames[u.target]+' duration';case 9:return 'Shorter '+skillNames[u.target]+' cooldown';case 10:return '×'+u.factor+' '+D.products[u.beneficiary].name+' income';case 11:return '×'+u.factor+' income for '+u.group.map(i=>D.products[i].name).join(' & ');default:return u.name;}}
function eligible(u){return fx().upgrades[u.id].eligible&&!owned(u.id);}
const matchesTarget=u=>{if(state.target==='all')return true;const target=Number(state.target);if(state.category==='Skills')return [7,8,9].includes(u.effect)&&u.target===target;if(state.category==='Products')return [0,1,10].includes(u.effect)&&u.target===target||u.beneficiary===target||u.group?.includes(target);return true;};
const scopeName=()=>state.target==='all'?'':state.category==='Skills'?skillNames[Number(state.target)]:state.category==='Products'?D.products[Number(state.target)]?.name||'':'';
function matches(u){const v=fx().upgrades[u.id],isOwned=owned(u.id);return (state.category==='All'||category(u)===state.category)&&matchesTarget(u)&&(!state.search||[u.name,u.id,effect(u)].join(' ').toLowerCase().includes(state.search.toLowerCase()))&&(state.view==='Full'||state.view==='Owned'&&isOwned||state.view==='Available'&&!isOwned&&v.eligible||state.view==='Upcoming'&&!isOwned&&!v.eligible);}
const upgradeIconNames=['product-profit','product-cost','tap-direct','tap-linked','tap-cost','global-profit','upgrade-cost','skill-power','skill-duration','skill-cooldown','product-link','product-group'];
function upgradeArt(u){return `<img id="${scope}-upgrade-art-${u.id}" class="upgrade-icon" src="assets/upgrades/${upgradeIconNames[u.effect]}.png" alt="" aria-hidden="true" decoding="async">`;}
function upgradeRow(u){const v=fx().upgrades[u.id],has=owned(u.id),can=eligible(u)&&v.price.value<=funds()&&!blocked();return `<article class="sheet-row upgrade-row" data-item-id="${u.id}" data-upgrade-effect="${u.effect}">${upgradeArt(u)}<div class="plain-detail"><h2>${esc(u.name)}</h2><p>${esc(effect(u))}</p><span class="detail-cue ${!v.eligible&&!has?'requirement':''}">${has?'Owned this run':!v.eligible?esc(u.requirementText):'Available'}</span></div>${b('BuyUpgrade',u.id,has?'Purchased':cash(v.price)+`<small>${!v.eligible?'Requirements':'Buy upgrade'}</small>`,'action row-action',!can||has)}</article>`;}
function sampleRows(){const next=D.upgrades.filter(eligible).sort((a,b)=>fx().upgrades[a.id].price.value-fx().upgrades[b.id].price.value||a.id.localeCompare(b.id)).slice(0,10);return next.length?next.map(upgradeRow).join(''):'<p class="intro">All upgrades purchased this run.</p>';}
function catalogue(){return `<input data-action="Filter" data-param="search" id="catalogue-search" class="search-box" type="search" placeholder="Search all 1,000 upgrades…" aria-label="Search upgrades" value="${esc(state.search)}"><div class="native-filters">${b('Filter','category',state.category,'action secondary')}${b('Filter','view',state.view,'action secondary')}</div><div id="catalogue-results">${catalogueResults()}</div>`;}

function catalogueResults(){const list=state.condition==='empty'?[]:D.upgrades.filter(matches),pages=Math.max(1,Math.ceil(list.length/20));state.page=Math.min(state.page,pages-1);return `<p class="catalogue-count">${list.length} matching · ${state.category}${scopeName()?' · '+esc(scopeName()):''} / ${state.view}</p>`+(list.length?list.slice(state.page*20,state.page*20+20).map(upgradeRow).join(''):`<div class="empty-state">No upgrades match this view.<br>Try a different filter or search.</div>`)+`<div class="catalogue-actions">${b('CataloguePage','previous','Previous','action secondary',state.page===0)}<span>Page ${state.page+1} / ${pages}</span>${b('CataloguePage','next','Next','action secondary',state.page===pages-1)}</div>`;}
function projection(u){const v=fx().upgrades[u.id].projection;if(!v)return p('Already purchased for this run. Its effect is included in your current earnings.');let html=p(`Normal sales <strong>${cash(v.normalBefore)} → ${cash(v.normalAfter)}/s</strong>`)+p(`Per tap <strong>${cash(v.tapBefore)} → ${cash(v.tapAfter)}</strong>`);if(v.costCategory!=='None')html+=p(`${{ProductLevels:'Product level',TapLevels:'Tap training',CashUpgrades:'Cash upgrade'}[v.costCategory]} price <strong>${cash(v.costBefore)} → ${cash(v.costAfter)}</strong>`);if(category(u)==='Skills')html+=p(`Power ${v.skillPowerBefore} → ${v.skillPowerAfter}<br>Duration ${v.durationBefore}s → ${v.durationAfter}s<br>Cooldown ${v.cooldownBefore}s → ${v.cooldownAfter}s`);return html;}
function productOverview(){
 const i=state.product,x=D.products[i],level=state.levels[i],q=fx().levelQuotes[i]['1'],m=productMilestone(level),atCap=level>=100000;
 const progress=(percent,label,description)=>`<div class="product-overview-progress" role="progressbar" aria-label="${esc(description)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-valuetext="${esc(description)}"><span style="width:${percent}%"></span><strong>${label}</strong></div>`;
 const minimum=Math.min(...state.levels),next=minimum>=100000?0:minimum<50?50:(Math.floor(minimum/100)+1)*100,met=next?state.levels.filter(n=>n>=next).length:8,multiplier=2**((minimum>=50?1:0)+Math.floor(minimum/100));
 const synergy=`<article class="product-overview-card"><h3>${next?'Next synergy bonus':'Synergy complete'}</h3>${progress(met/8*100,next?met+'/8 products at Lvl '+next:'Complete','All product synergy progress')}<p class="product-overview-reward">All products: ×${multiplier}${next?' → another ×2':''}</p><p class="product-overview-explanation">${next?state.levels.map((n,j)=>n<next?esc(D.products[j].name)+' ('+n+')':'').filter(Boolean).join(', '):'All synergy milestones reached.'}</p></article>`;
 return `<div class="product-overview-identity"><div class="product-overview-art">${art(i)}</div><div><h3>${esc(x.name)}</h3><p class="product-overview-level">Lvl : <strong>${level}</strong></p><p class="product-overview-subtitle">${['Basic','Signature I','Premium · Signature IV','Showcase · Signature X'][Number(productImage(i).match(/-(\d)\.png$/)?.[1]||0)]}</p></div></div><p class="product-overview-earnings">Earns <strong>${cash(q.productBefore)} / second</strong></p><article class="product-overview-card"><h3>${atCap?'All level milestones reached':'Lvl '+m.next+' · profit ×'+milestoneReward(m.next)}</h3>${progress(atCap?100:m.percent,atCap?'Maximum level':'Lvl '+m.next,atCap?'Maximum level reached':`Level ${level}; ${Math.round(m.percent)}% from level ${m.previous} to ${m.next}`)}<p class="product-overview-reward">${atCap?'Fully levelled': 'Milestone reward'}</p><p class="product-overview-explanation">${atCap?'All automatic level bonuses are active.':'Milestones apply automatically. Buy cash upgrades for boosts, then use Max to level up.'}</p></article>${synergy}`;
}
function productDetail(tap=false){if(!tap)return productOverview();const q=levelQuote(-1);return card('Train your tapping',`Level ${q.beforeLevel} → ${q.afterLevel}<br>Per tap ${cash(q.tapBefore)} → ${cash(q.tapAfter)}<br>${q.nextMilestone?'Next: Lvl '+q.nextMilestone+' · ×'+milestoneReward(q.nextMilestone):'All milestones reached'}`)+b('Quantity','tap:cycle','Cycle quantity: 1 / 10 / 100 / Max','action secondary buy-all')+card('Growing your shop','Training improves manual taps and Helping Hands. Tap milestones multiply profit at 10, 25, 50, 100 and every 100 levels.');}

function skillTiming(seconds){const n=Math.ceil(seconds);return n>=60?Math.floor(n/60)+'m'+(n%60?' '+n%60+'s':''):n+'s';}
function skillEffect(i,s){return i===0?'×'+s.power+' automatic sales. Taps +25%.':i===1?s.power+' automatic taps per second':s.power+' seconds of sales, instantly.';}
function skills(){return '<div class="skills-quick-list">'+skillNames.map((name,i)=>{
 const s=fx().skills[i],view=skillPresentation(i),phase=view.phase;
 const activate=b('ActivateSkill',i,phase==='ready'?'Activate':phase==='locked'?'Locked':phase==='active'?'Active':'Cooldown','action skill-activate',phase!=='ready'||blocked()).replace('<button ','<button aria-label="Activate '+name+'" ');
 const details=b('Navigate','SkillDetail:'+i,'Details','skill-details').replace('<button ','<button aria-label="Details for '+name+'" ');
 return '<article class="skill-quick-row" id="'+scope+'-skill-'+s.unlockId+'" data-skill-index="'+i+'" data-state="'+phase+'" data-unity-collection-id="skills" data-unity-template-id="skill-quick-row" data-unity-item-key="'+s.unlockId+'"><span class="skill-portrait" aria-hidden="true">'+icon(phase==='locked'?'lock':['burst','hands','order'][i])+skillRing(view)+'</span><div class="skill-row-copy"><h3>'+name+'</h3><span class="skill-status skill-row-state">'+skillStatus(view)+'</span><p class="skill-effect">'+skillEffect(i,s)+'</p><p class="skill-timing"><span>Duration: '+(i===2?'Instant':skillTiming(s.duration))+'</span><span>Cooldown: '+skillTiming(s.cooldown)+'</span></p></div><div class="skill-row-actions">'+activate+details+'</div></article>';
 }).join('')+'</div>';}

function skillHeroAction(i,view){return view.phase==='ready'?'Activate '+skillNames[i]:view.phase==='active'?'Active · '+skillTime(view.remaining):view.phase==='cooldown'?'Ready in '+skillTime(view.remaining):'Skill locked';}
function skillDetail(){
 const i=state.skill,s=fx().skills[i],view=skillPresentation(i);
 const tiles=i===0
  ?[['stats','×'+s.power,'Automatic sales'],['player','+25%','Manual & Helping Hands taps']]
  :i===1
   ?[['stats',s.power+'/sec','Automatic taps'],['player',cash(displayTap()),'Payout per automatic tap']]
   :[['stats',cash(s.payout),'Instant payout'],['player',s.power+' sec','Normal sales equivalent']];
 return `<article class="skill-hero" id="${scope}-hero-${s.unlockId}" data-skill-hero="${i}" data-state="${view.phase}" data-unity-item-key="${s.unlockId}">
  <div class="skill-hero-art" aria-hidden="true">${icon(['burst','hands','order'][i])}${skillRing(view)}</div>
  <span class="skill-hero-status">${skillStatus(view)}</span>
  <div class="skill-hero-effects">${tiles.map(([image,value,label])=>`<section class="skill-effect-tile">${icon(image)}<strong>${value}</strong><span>${label}</span></section>`).join('')}</div>
  <div class="skill-hero-timing"><div><small>DURATION</small><strong>${i===2?'Instant':skillTime(Math.floor(s.duration))}</strong></div><div><small>COOLDOWN</small><strong>${skillTime(Math.floor(s.cooldown))}</strong></div></div>
  <p class="skill-hero-note">Normal sales are the base for tap links and Bulk Order. Cooldown starts at activation.</p>
 </article>`;
}
function pullCost(count){const needed=count===5?4:1;return state.credits>=needed?{credits:needed,kk:0,label:needed+' free pull'+(needed===1?'':'s')}:{credits:0,kk:needed*100,label:(needed*100)+' KK'};}
function talent(){const one=pullCost(1),five=pullCost(5);return (state.reveal?b('Navigate','DrawReveal','Reveal your saved card','action maroon buy-all'):'')+`<div class="legacy-draw-actions">${b('Draw','1','1× pull<small>'+one.label+'</small>','action',locked()||!!state.reveal||state.kk<one.kk||blocked())}${b('Draw','5','5× pull<small>'+five.label+'</small>','action',locked()||!!state.reveal||state.kk<five.kk||blocked())}</div>`+`<p class="native-legacy-state">${locked()?'Complete your first prestige to unlock Talent.':''}</p>`+[0,1,2].map(t=>`<h3 class="collection-title">${['Common','Rare','Legendary'][t]}<span class="rarity-discovered">${state.cardLevels.filter(x=>x>0).length} / ${D.cards.length} discovered</span></h3><div class="collection-grid" style="--native-card-height:${120+7*(1-1/Math.ceil(D.cards.filter(c=>c.tier===t).length/4))-6}px">${D.cards.map((c,i)=>({c,i})).filter(x=>x.c.tier===t).map(({c,i})=>b('Navigate','CardDetail:'+i,`<img class="native-mini-frame" src="assets/cards/folk-${['common','rare','legendary'][t]}.png" alt="">${cardIcon(c)}<strong>${esc(c.name)}</strong><small class="card-level-badge" aria-label="${state.cardLevels[i]?'Level '+state.cardLevels[i]:'Undiscovered'}">${'Lvl '+state.cardLevels[i]}</small>`, 'talent-card '+['common','rare','legendary'][t]+(!state.cardLevels[i]?' unowned':''),!state.cardLevels[i])).join('')}</div>`).join('');}
function cardIcon(c){return `<span class="row-art talent-art" aria-hidden="true"><img src="assets/cards/art/${c.id}.png" alt="" decoding="async"></span>`;}
function cardEffect(c,m){const n=num(m);if(c.effect===7)return 'Offline income efficiency '+((m?.value||.5)*100).toFixed(2)+'%';return ['Product income ×','Product level prices ×','Tap & Helping Hands payout ×','Tap training prices ×','Skill cooldown ×','Skill duration ×','Bulk Order payout ×','','Offline storage: ','Normal sales & direct tap income ×','Cash upgrade prices ×'][c.effect]+n+(c.effect===8?' hours':'');}
function cardDetail(){const i=state.card,c=D.cards[i],level=state.cardLevels[i],m=fx().cards[i].examples[Math.min(64,level)],tier=['Common','Rare','Legendary'][c.tier];const amount=c.effect===7?((m?.value||.5)*100).toFixed(0)+'%':c.effect===8?num(m)+' hours':'×'+num(m);const benefit=c.effect===0?D.products[c.target].name+' income':c.effect===1?D.products[c.target].name+' level prices':({2:'Tap & Helping Hands payout',3:'Tap training prices',4:skillNames[c.target]+' cooldown',5:skillNames[c.target]+' duration',6:'Bulk Order payout',7:'Offline income efficiency',8:'Offline storage',9:'Normal sales & direct tap income',10:'Cash upgrade prices'})[c.effect];const flavor=c.effect===0?'A brighter display. A busier shop.':c.effect===1?'Stock up wisely. Grow your shop.':({2:'Every sale starts with a helping hand.',3:'A little practice goes a long way.',4:'Ready for the next rush.',5:'Keep the celebration going.',6:'Bigger orders. Brighter celebrations.',7:'The bazaar earns while you rest.',8:'More time away. More earnings saved.',9:'A name the whole bazaar remembers.',10:'A better deal for a brighter shop.'})[c.effect];return `<article class="full-talent-card ${tier.toLowerCase()}"><header class="full-card-heading"><h3>${esc(c.name)}</h3><span class="full-card-level">Lvl ${level}</span><span class="full-card-rarity">· ${tier} ·</span></header><div class="full-card-art">${cardIcon(c)}</div><p class="full-card-benefit">${esc(cardEffect(c,m))}</p><div class="full-card-divider" aria-hidden="true">◆</div><p class="full-card-flavor">${esc(flavor)}</p><p class="full-card-permanent">· Permanent bonus ·</p></article>`;}
function prestige(){const q=fx().prestige;return `<strong class="native-reward">${q.Eligible?'+'+q.fame+' Fame':cash(fx().earned)+' earned'}</strong>`+card('Your next beginning',`Run target · ${cash(q.target)}<br>Products ×${num(q.multiplier)} · taps ×${num(q.tapMultiplier)}<br>${q.credits} free Talent draws<br>Next run target · ${cash(q.nextTarget)}`)+card('Resets','Run cash · product and tap levels<br>Cash upgrades · skills and active effects')+card('Stays','Fame · Talent · KK · free draws<br>Lifetime discoveries · decorations');}

function offlineTiming(){const level=i=>Number(state.cardLevels[i])||0,eff=.5+.5*level(24)/(level(24)+5),cap=8+12*level(25)/(level(25)+5),away=10,stored=Math.min(away,cap);return {eff,cap,away,stored,extent:Math.max(away,cap)};}
const offlineBase=()=>{const t=offlineTiming();return (fx().normal.value||0)*t.stored*3600*t.eff;};
function offlineAdOutcome(){
 if(state.offlineAd!=='watching'||!state.stack.some(e=>e.name==='Offline'))return;
 if(state.condition==='delivered'&&!state.offlineDoubled){state.offlineDoubled=true;state.offlineAd='rewarded';notice('Ad completed · your offline reward is doubled.');}
 else if(['cancelled','failed','unavailable','save-error'].includes(state.condition)){state.offlineAd=state.condition;notice('No ad bonus added. Your normal offline earnings are safe.');}
}
function offline(){
 const t=offlineTiming(),doubled=state.offlineDoubled,status=state.offlineAd,h=n=>Number.isInteger(n)?n+'h':n.toFixed(1)+'h',base=offlineBase();
 const note=doubled?'Bonus saved. Continue when you’re ready.':status==='watching'?'Your normal reward stays saved if you close the ad.':['failed','unavailable','save-error','cancelled'].includes(status)||state.condition==='unavailable'?'Ad not completed. Your normal reward is already saved.':'Complete an ad to add one extra reward.';
 return `<div class="afk-timeline"><div class="afk-earnings"><img src="parity/assets/icons/coins.png" alt=""><p>OFFLINE EARNINGS</p><strong>${money(base*(doubled?2:1))}</strong><span>${doubled?'2× reward collected':'Normal reward · already saved'}</span></div><section class="afk-storage"><header><h3>Offline storage</h3><span>${t.away>=t.cap?'CAP REACHED':'ROOM TO EARN'}</span></header><div class="afk-timeline-space"><div class="afk-track" role="progressbar" aria-label="Offline time stored" aria-valuemin="0" aria-valuemax="${t.cap}" aria-valuenow="${t.stored}" aria-valuetext="${h(t.stored)} stored of ${h(t.cap)} cap; ${h(t.away)} away"><div class="afk-gold" style="width:${t.stored/t.extent*100}%"></div><strong>${h(t.stored)} / ${h(t.cap)} stored</strong><span class="afk-cap" style="left:${t.cap/t.extent*100}%"><b>${h(t.cap)} cap</b></span></div><div class="afk-ticks"><span>0h</span><span>${t.away>t.cap?h(t.away-t.cap)+' beyond cap':h(t.cap-t.stored)+' storage remaining'}</span><span>${h(t.away)} away</span></div></div><div class="afk-efficiency"><span style="--eff:${t.eff*100}%" aria-hidden="true"></span><strong>${(t.eff*100).toFixed(1).replace('.0','')}% efficiency</strong></div></section><section class="afk-comparison"><div><h3>Normal reward</h3><strong>${money(base)}</strong><img src="parity/assets/icons/coins.png" alt=""></div><div><h3>With an ad</h3><strong>${money(base*2)}</strong><img src="parity/assets/icons/coins.png" alt=""></div></section><p class="afk-ad-status" role="status">${note}</p></div>`;
}


function settings(){return ['music','sound','motion'].map((k,i)=>`<article class="sheet-row settings-row"><div><h3>${['Music','Sound effects','Reduced motion'][i]}</h3><p>${['Festival atmosphere','Taps and celebrations','Settle effects instantly'][i]}</p></div>${b('Setting',k,`<span class="setting-switch-track" aria-hidden="true"><span class="setting-switch-state">${state.settings[k]?'ON':'OFF'}</span><span class="setting-switch-thumb"></span></span>`,'toggle').replace('class="toggle"',`class="toggle" role="switch" aria-label="${['Music','Sound effects','Reduced motion'][i]}" aria-checked="${state.settings[k]}"`)}</article>`).join('')+b('Navigate','Naming','Shop name','action secondary buy-all settings-name')+b('Navigate','Privacy','Privacy','action secondary buy-all')+b('Navigate','Help','How to play','action secondary buy-all')+b('Navigate','TutorialHelp','Tutorial guidance','action secondary buy-all')+(Q.get('privacy')==='required'?b('AdPrivacyOptions','','Ad privacy choices','action secondary buy-all'):'')+(developmentBuild?b('Navigate','DeveloperReset',state.account==='Guest'?'Reset game (developer)':'Reset game · guest mode only','action secondary buy-all',!canResetDevelopmentGame()):'');}
function fitNativeTitles(){const scale=parseFloat(document.documentElement.style.getPropertyValue('--s'))||1;for(const e of document.querySelectorAll('.full-card-heading h3')){const startup=e.closest('.native-startup'),max=e.matches('.full-card-heading h3')?21:e.tagName==='H1'?124/3:66/3,min=e.matches('.full-card-heading h3')?15.12:e.tagName==='H1'?90/3:48/3;e.style.fontSize=max*scale+'px';for(let size=max;size>min&&e.scrollWidth>e.clientWidth+.5;size-=.25)e.style.fontSize=Math.max(min,size-.25)*scale+'px';}}
function stats(){const f=fx(),count=D.upgrades.filter(u=>f.upgrades[u.id].ever||owned(u.id)).length,stage=[0,100,250,500,750,1000].filter(n=>n<=count).length-1,names=['Opening stall','Marigold welcome','Lantern glow','Embroidered counter','Festival bunting','Raja crest'];return card('This run',`Earned this run: ${cash(f.earned)}<br>Normal sales: ${cash(displayNormal())} /s<br>Manual taps: ${f.taps}<br>Tap payout: ${cash(displayTap())}<br>Owned upgrades: ${D.upgrades.filter(u=>owned(u.id)).length} / 1,000`)+card('Your whole journey',`Prestiges: ${f.prestiges}<br>Fame: ${f.fame}<br>Discovered upgrades: ${count} / 1,000<br>Talent cards: ${state.cardLevels.filter(x=>x>0).length} / 28<br>Lifetime earnings: ${cash(f.lifetime)}`)+card('Your decorations',`Shop ${stage+1}/6 · ${names[stage]}<br>${stage===5?'All shop decorations earned.':count+' unique purchases · Next: '+names[stage+1]+' at '+[0,100,250,500,750,1000][stage+1]}<br>Decorations stay after Prestige. Product displays rebuild.`);}

function purchase(){const x=D.packs[state.pack];return hero(7,esc(x.name),x.kajuKatli.toLocaleString('en-IN')+' KK').replace(art(7),'<span class="row-art currency-pack-art">'+window.classicCurrency.icon({decorative:true})+'</span>')+card('A treat for your Talent',p(x.kajuKatli/100+' draws · 100 KK per draw')+`<strong class="big-amount">₹${x.designInr.toLocaleString('en-IN')}</strong>`+p('Example app-store price. No real payment in this HTML preview.'))+p('Each draw uses the same pool: Common 75%, Rare 22%, Legendary 3%. No pack guarantees a rarity.')+`<p class="small-copy">Choose an outcome below to review the purchase flow.</p><div class="status-list">${['delivered','pending','cancelled','failed'].map(s=>b('PurchaseResult',s,{delivered:'Preview successful purchase',pending:'Preview pending purchase',cancelled:'Preview cancellation',failed:'Preview verification failure'}[s],s==='delivered'?'action':'action secondary')).join('')}</div>`;}
function appearance(){
 const displays=['Original display','Signature I · cash upgrade this run','Signature IV · cash upgrade this run','Signature X · cash upgrade this run'];
 const names=['Opening stall','Marigold welcome','Lantern glow','Embroidered counter','Festival bunting','Raja crest'];
 const decoration=['shelf','garland','lantern','apron','bunting','crest'];
 return card('Eight familiar shelves',p('Your products occupy their painted shelf compartments. Talent, Fame and lifetime discoveries persist through prestige.'))
  +displays.map((label,i)=>`<div class="appearance-row"><img src="${i?'parity/assets/looks/phuljhari-'+i+'.png':'assets/products/icons/sparklers.png'}" alt=""><p>${label}</p></div>`).join('')
  +card('Permanent shop decorations',p('Earned from unique lifetime upgrade purchases. Decorations stay after prestige; product displays rebuild.'))
  +names.map((name,i)=>`<div class="appearance-decoration"><img src="${i?'parity/assets/decorations/'+decoration[i]+'.png':'parity/assets/icons/shelf.png'}" alt=""><p>${name}<br>${[0,100,250,500,750,1000][i]} unique purchases</p></div>`).join('');
}

function sheet(n){let title=n,body='',footer='';const back=()=>b('Close','','Back','action secondary');switch(n){
 case'Guidance':{const t=window.nativeGuideTopics.find(t=>t.id===state.tip)||window.nativeGuideTopics.find(t=>t.id==='product-levels');state.tip=t.id;title='A little guidance';body=card(t.title,esc(t.body));footer=b('LearnTip',state.tip,'Got it','action');}break;
 case'Upgrades':title='Cash upgrades';body=catalogue();footer=b('ReviewBatch','','Review Buy All','action')+back();break;
 case'ProductDetail':title=D.products[state.product].name;body=productDetail();break;
 case'TapTraining':title='Salesmanship';body=productDetail(true);{const q=levelQuote(-1);footer=b('BuyLevels',-1,state.levelBought.has(-1)?'Training previewed':'Train ×'+q.count+' · '+cash(q.cost),'action',!q.affordable||state.levelBought.has(-1)||funds()===0||blocked())+back();}break;
 case'Achievements':title='Your achievements';body=window.classicAchievements.render(state,fx(),D,b,esc,blocked());footer='<p>Progress stays after prestige.</p>'+b('Close','','Back to your stall','action secondary');break;
 case'Skills':title='Your skills';body=skills();footer='<p class="skills-reset-note">Skills reset on prestige. Talent bonuses apply after rebuying.</p>';break;
 case'SkillDetail':title=skillNames[state.skill];body=skillDetail();footer=b('ActivateSkill',state.skill,skillHeroAction(state.skill,skillPresentation(state.skill)),'action skill-hero-activate',skillState(state.skill)!=='ready'||blocked());break;
 case'CardDetail':title=D.cards[state.card].name;body=cardDetail();break;
 case'DrawReveal':title='A little festival magic';{const r=state.reveal||{card:0,before:0,after:1},c=D.cards[r.card],tier=['common','rare','legendary'][c.tier];body=`<p class="pull-progress">${r.results?.length>1?'Card '+(r.index+1)+' / '+r.results.length:'Your card awaits'}</p><div class="flip-stage ${tier}"><div class="flip-card"><div class="flip-face flip-back"><img src="assets/cards/shared-card-back.png" alt="Face-down festival card"></div><div class="flip-face flip-front" aria-hidden="true">${cardIcon(c)}<span class="flip-level">Lvl ${r.after}</span><strong>${esc(c.name)}</strong></div></div></div><div class="flip-result" aria-hidden="true"><span class="pill ${tier}">${tier}</span><h3>${r.before?'Level '+r.before+' → '+r.after:'New card discovered!'}</h3><p>${esc(cardEffect(c,fx().cards[r.card].examples[Math.min(64,r.after)]))}</p></div>`;footer=b('Reveal','continue',r.results&&r.index+1<r.results.length?'Next card':'Continue','action',true);}break;
 case'Prestige':title='A brighter beginning';body=prestige();footer=b('Prestige','confirm','Begin again','action maroon',!fx().prestige.Eligible||state.condition==='stale'||blocked())+b('Close','','Keep growing','action secondary');break;
 case'Offline':title='Welcome back';body=offline();footer=b('OfflineAd','watch',state.offlineDoubled?'2× reward collected':state.offlineAd==='watching'?'Watching ad…':'Watch ad for 2× rewards','action',state.offlineDoubled||state.offlineAd==='watching'||blocked()||offlineBase()<=0)+b('Offline','close','Continue','action secondary');break;
 case'Statistics':title='Your shop in numbers';body=stats();footer=back();break;
 case'Settings':title='Settings';body=settings();footer='';break;
 case'TutorialHelp':title='Tutorial guidance';body=card('Tutorial status',p('Replay guidance at your current progress. Skipping keeps all progress.'))+b('TutorialResume','','Continue guidance','action secondary buy-all')+b('TutorialReplay','','Replay guidance','action secondary buy-all')+b('TutorialSkip','','Skip tutorial','action secondary buy-all');footer=back();break;
 case'DeveloperReset':title='Reset game?';body=card('Start a fresh game',p('Erase all local guest progress, including cash, products, upgrades, cards, Fame and settings. This cannot be undone. Google account saves are unchanged.'));footer=b('DeveloperReset','','Reset game','action maroon',!canResetDevelopmentGame())+b('Close','','Cancel','action secondary');break;
 case'Naming':title='Make it your own';body=card('Name your shop',p('A name for your little corner of the festival.')+`<label for="shop-name" class="small-copy">Shop name</label><input id="shop-name" class="name-input" maxlength="24" value="${esc(state.name)}" autocomplete="off" aria-describedby="shop-name-help shop-name-error"><p id="shop-name-help" class="small-copy">Up to 24 characters.</p><p id="shop-name-error" class="inline-error" role="alert" hidden>Enter a shop name first.</p>`);footer=b('Rename','','Save shop name')+back();break;
 case'Privacy':title='Your privacy';body=card('Your progress',p('Your game is saved on this device. Cloud saves and cross-device sync are currently unavailable.'))+card('Purchases & information',p('A real store purchase must be verified before Kaju Katli is delivered. No payment, authentication or analytics service runs in this preview.'))+card('Control your experience',p('Music, sound and reduced motion are available in Settings. Recovery choices explain which save will be used before you continue.'));footer=back();break;


 case'SaveRecovery':title='Your progress needs attention';body=card('We could not open this save',p('Keep the existing files while retrying loading or saving. Gameplay stays paused until recovery succeeds.'))+`<div class="status-list">${b('Recovery','retry','Try loading again')}${b('Recovery','exit','Keep files and leave','action secondary')}</div>`;break;
 case'RecoveryExit':title='Your files are safe';body=p('You have left the blocked game. In Unity this action exits the application. This preview keeps the browser open.');footer=b('Recovery','exit','Keep files and leave');break;
 case'Purchase':title='Kaju Katli pack';body=purchase();footer=back();break;
 case'BuyAll':title='Review your purchases';{const q=state.batch;body=q?(state.condition==='stale'?'<p class="inline-error" role="status">Your progress changed. Refresh this review before buying.</p>':'')+card('Only the reviewed upgrades',p('Scope · '+esc(q.label))+p('Budget · '+money(q.budget))+`<strong class="big-amount">${q.ids.length} upgrades · ${money(q.total)}</strong>`+p(q.first+' first purchases'))+`<ol class="batch-list">${q.ids.map((id,i)=>`<li><span>${esc(D.upgrades.find(u=>u.id===id).name)}</span><strong>${money(q.prices[i])}</strong></li>`).join('')}</ol>`+p('Normal sales continue. New earnings never add upgrades to this list.')+p('Product levels, tap levels, Talent and KK are not included.'):p('No purchases to review.');footer=b('ConfirmBatch','','Buy reviewed upgrades','action',!q?.ids.length||state.condition==='stale'||blocked())+b('ReviewBatch','refresh','Refresh review','action secondary')+back();}break;
 case'Appearance':title='Your shop’s journey';body=appearance();footer=back();break;
 case'Help':title='A little guidance';body=card('Start with a spark',p('Start with ₹0 and tap the counter to earn ₹1 per tap. Save ₹30, then buy your first Phuljhari display in Products. Tap training starts at ₹10. Products earn automatically; tap the counter on any main tab for extra cash.'))+card('Grow your way',p('Player contains tap training and the full upgrade browser. Products contains your eight families. Legacy brings together Fame and Talent. Shop contains Kaju Katli packs.'))+card('Begin again, stronger',p('Prestige resets the run while keeping Fame, Talent, KK, free credits, discoveries and decorations.'));footer=back();break;
 case'Odds':title='Every card has a chance';body=card('Same pool for every draw',p('Common · 75% / 16 cards = 4.6875% each')+p('Rare · 22% / 10 cards = 2.2% each')+p('Legendary · 3% / 2 cards = 1.5% each'))+p('Free draws and 100-KK draws use the same pool. Each duplicate adds one card level. There is no guaranteed rarity from buying a pack.');footer=back();break;
 case'Exact':title='A closer look';body=`<div class="exact-values">${state.exact||''}</div>`+p('Amounts are exported from the native core’s stored magnitude; display rounding does not change the quote.');footer=back();break;
 default:title='Something needs attention';body=p('This example is not available. Return to your shop.');footer=back();
 }if(state.condition==='save-error')body='<p class="inline-error">Progress could not be saved. Purchases are paused; nothing will be spent until saving is available.</p>'+body;
 return {title,body,footer};}
function setTab(n){if(!tabs.includes(n))return;closeAll();state.tab=n;$('app').dataset.tab=n;tabs.forEach(t=>$('panel-'+t).hidden=t!==n);tabs.slice(1).forEach(t=>$('nav-'+t).setAttribute('aria-pressed',String(t===n)));$('review-screen').value=n;document.querySelector('.shelves').inert=false;document.querySelector('.shelves').setAttribute('aria-hidden','false');syncContract();requestAnimationFrame(updateScrollCues);motion.panel($('panel-'+n),$('nav-'+n));}
function syncSheetLayers(){state.stack.forEach((entry,i)=>{const top=i===state.stack.length-1;entry.el.hidden=false;entry.el.inert=!top;entry.el.style.zIndex=String(100+i);if(top)entry.el.removeAttribute('aria-hidden');else entry.el.setAttribute('aria-hidden','true');entry.el.querySelector('.modal-card')?.setAttribute('aria-modal',String(top));});}
function open(name,from){if(['Account','Welcome','AccountCompare','Handoff','SignOut','Promote','RecoveryConfirm'].includes(name))return;if(name==='DeveloperReset'&&!canResetDevelopmentGame())return;const existing=state.stack.findIndex(e=>e.name===name);if(existing>=0){state.stack.splice(existing+1).forEach(e=>e.el.remove());syncSheetLayers();state.stack.at(-1).el.querySelector('button:not(:disabled),input')?.focus();return;}const old=state.stack.at(-1);if(old)old.scroll=old.el.querySelector('.modal-body').scrollTop;const el=document.createElement('section');el.className='modal-layer';el.dataset.screen=name;const entry={name,el,opener:from||document.activeElement,openerIdentity:focusIdentity(from||document.activeElement),scroll:0,selection:{product:state.product,skill:state.skill,card:state.card,upgrade:state.upgrade}};state.stack.push(entry);$('sheets').append(el);renderSheet(entry);$('app-inner').inert=true;syncSheetLayers();(el.querySelector('button:not(:disabled),input,select')||el.querySelector('.modal-card'))?.focus();$('app-inner').setAttribute('aria-hidden','true');motion.sync();$('review-screen').value=[...$('review-screen').options].some(o=>o.value===name)?name:'';}
function renderSheet(entry=state.stack.at(-1)){
 if(!entry)return;
 const focused=focusIdentity(),y=entry.el.querySelector('.modal-body')?.scrollTop||entry.scroll||0;
 scope='sheet-'+entry.name+'-'+state.stack.indexOf(entry);serial=0;
 const v=sheet(entry.name),hasClose=!['SaveRecovery','RecoveryExit'].includes(entry.name);
 if(!['CardDetail','Guidance','Skills','SkillDetail','DrawReveal','ProductDetail','Offline'].includes(entry.name))v.body=guideRow(entry.name)+v.body;
 const close=hasClose?b('Close','','<span aria-hidden="true">×</span>','close').replace('class="close"','class="close" aria-label="Close '+entry.name+'"'):'';
 const infoTopic={ProductDetail:['product-levels','Product information'],Offline:['return-play','Offline earnings information']}[entry.name];
 const popupInfo=infoTopic?b('Tip',infoTopic[0],'<span aria-hidden="true">i</span>','popup-info').replace('class="popup-info"',`class="popup-info" aria-label="${infoTopic[1]}"`):'';
 entry.el.innerHTML=`<div class="modal-card${hasClose?' popup-has-close':''}" role="dialog" aria-modal="true" aria-labelledby="${scope}-title" tabindex="-1"><header class="modal-head"><h2 id="${scope}-title">${v.title}</h2>${entry.name==='Skills'?'<p class="skills-subtitle">Three ways to boost your shop</p>':''}</header>${close}${popupInfo}<output id="${scope}-status" class="sheet-notice" role="status" aria-live="polite" hidden></output><div class="modal-body">${v.body}</div><footer class="modal-footer">${v.footer}</footer></div>`;
 window.classicPopupRefresh.decorate(entry.el);window.classicUnityPresentation.apply(entry.el);window.classicCurrency.decorate(entry.el);entry.el.querySelector('.modal-body').scrollTop=y;syncContract();
 if(!entry.motionEntered){motion.sheet(entry.el);entry.motionEntered=true;}
 if(entry.name==='DrawReveal')startCardFlip(entry);
 requestAnimationFrame(fitNativeTitles);document.fonts.ready.then(fitNativeTitles);restoreFocus(focused);requestAnimationFrame(updateScrollCues);
}
function settleCardFlip(entry=state.stack.at(-1)){if(entry?.name!=='DrawReveal')return;const first=!entry.el.classList.contains('flip-settled');entry.el.classList.add('flip-settled');const progress=entry.el.querySelector('.pull-progress');if(progress&&!state.reveal?.results?.length||progress&&state.reveal?.results?.length===1)progress.textContent='Your card revealed';entry.el.querySelector('.flip-front')?.removeAttribute('aria-hidden');entry.el.querySelector('.flip-back')?.setAttribute('aria-hidden','true');entry.el.querySelector('.flip-result')?.removeAttribute('aria-hidden');const next=entry.el.querySelector('[data-action="Reveal"][data-param="continue"]');if(next)next.disabled=false;if(state.reveal)state.reveal.shownIndex=state.reveal.index||0;if(first){const stage=entry.el.querySelector('.flip-stage');motion.reveal(stage,stage.classList.contains('legendary')?'legendary':stage.classList.contains('rare')?'rare':'common');}}
async function startCardFlip(entry){entry.el.classList.remove('flip-running','flip-settled');if(state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches||state.reveal?.shownIndex===(state.reveal?.index||0)){settleCardFlip(entry);return;}const flip=entry.el.querySelector('.flip-card');await Promise.all([...flip.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));if(!flip.isConnected||entry.el.classList.contains('flip-settled'))return;flip.addEventListener('animationend',e=>{if(e.animationName==='festival-card-flip')settleCardFlip(entry);},{once:true});entry.el.classList.add('flip-running');}
function close(){const top=state.stack.at(-1);if(top?.name==='Offline'&&state.offlineAd==='watching')state.offlineAd='cancelled';if(top&&!['SaveRecovery','RecoveryExit'].includes(top.name))motion.dismiss(top.el);if(top?.name==='DrawReveal'){state.reveal=null;closeAll();renderPanels();setTab('Legacy');$('nav-Legacy').focus();return;}if(!top||['SaveRecovery','RecoveryExit'].includes(top.name))return;state.stack.pop().el.remove();const previous=state.stack.at(-1);if(previous){Object.assign(state,previous.selection);syncSheetLayers();$('review-screen').value=previous.name;}else{$('app-inner').inert=false;$('app-inner').removeAttribute('aria-hidden');$('review-screen').value=state.tab;}if(restoreFocus(top.openerIdentity)){}else if(top.opener?.isConnected&&!top.opener.closest('[hidden],[inert]'))top.opener.focus();else if(previous)previous.el.querySelector('button:not(:disabled)')?.focus();else $('nav-'+(state.tab==='Home'?'Player':state.tab)).focus();if(previous)previous.el.querySelector('.modal-body').scrollTop=previous.scroll;syncContract();requestAnimationFrame(updateScrollCues);}
function closeAll(){if(state.offlineAd==='watching')state.offlineAd='cancelled';$('notice').hidden=true;state.stack.forEach(x=>x.el.remove());state.stack=[];$('app-inner').inert=false;$('app-inner').removeAttribute('aria-hidden');}
function navigate(route,from){const [n,arg,arg2]=route.split(':');if(n==='Talent'){setTab('Legacy');return;}if(tabs.includes(n)){setTab(n);if(n==='Products'&&arg==='first'){$('scroll-Products').scrollTop=0;requestAnimationFrame(updateScrollCues);}return;}if(n==='Upgrades'&&arg){state.category=arg;state.target=arg2||'all';state.search='';state.view='Available';state.page=0;}if(n==='UpgradeDetail'){setTab('Player');return;}if(n==='ProductDetail'&&arg)state.product=Number(arg);if(n==='SkillDetail'&&arg)state.skill=Number(arg);if(n==='CardDetail'&&arg)state.card=Number(arg);if(n==='BuyAll'&&!state.batch)reviewBatch();else open(n,from);}
function refresh(){renderPanels();renderSheet();}
function reject(){if(state.condition==='save-error'){notice('Could not save. Nothing was spent. Retry after saving is available.');return true;}if(blocked()){notice('This action is unavailable. Your progress is unchanged.');return true;}return false;}
function reviewBatch(){
 const source=fx().batches[state.category+(state.target==='all'?'':':'+state.target)];
 const native=!state.search&&!state.bought.size&&funds()>0;
 let ids=[],prices=[],total=0;
 if(native&&source){ids=[...source.ids];prices=source.prices.map(x=>x.value);total=source.cost.value;}
 else {for(const u of D.upgrades.filter(matches).filter(eligible).sort((a,b)=>fx().upgrades[a.id].price.value-fx().upgrades[b.id].price.value)){const cost=fx().upgrades[u.id].price.value;if(total+cost<=funds()){ids.push(u.id);prices.push(cost);total+=cost;}}}
 state.batch={ids,prices,total,budget:funds(),first:ids.filter(id=>!fx().upgrades[id].ever).length,label:[state.category,state.target==='all'?'All targets':state.category==='Skills'?skillNames[Number(state.target)]:D.products[Number(state.target)]?.name,state.search?'“'+state.search+'”':''].filter(Boolean).join(' / '),native};
 $('review-status').textContent=native?'Frozen Buy All example exported from the C# core, including current discounts.':'Filtered interaction example uses frozen prices. Native scope re-quoting is deferred to the Unity stage.';
 if(state.stack.at(-1)?.name==='BuyAll')renderSheet();else open('BuyAll');
}
function handle(action,param,from){log(action,param);switch(action){
 case'TutorialResume':case'TutorialReplay':closeAll();if(window.tutorialPreview)window.tutorialPreview.dispatch(action==='TutorialReplay'?'ReplayTutorial':'ResumeTutorial');else location.assign('../Tutorial/?step=welcome');break;
 case'TutorialSkip':closeAll();if(window.tutorialPreview)window.tutorialPreview.dispatch('SkipTutorial');else{setTab('Home');notice('Guidance skipped in this preview. Your stall progress is unchanged.');}break;
 case'AdPrivacyOptions':notice('Ad privacy choices are managed by the native consent SDK. No ad service runs in this preview.');break;
 case'DeveloperReset':if(state.stack.at(-1)?.name!=='DeveloperReset'||!canResetDevelopmentGame())break;state.settings={music:true,sound:true,motion:false};state.name='DIWALI DUKAAN';reset('new',false);setTab('Home');motion.sync();notice('Your fresh guest shop is ready.');break;
 case'Tip':if(blocked())break;state.tip=param;open('Guidance',from);break;
 case'LearnTip':if(blocked())break;state.learned.add(param);close();renderPanels();break;
 case'Tab':setTab(param===state.tab?'Home':param);break;
 case'Navigate':navigate(param,from);break;
 case'Close':close();break;
 case'ClaimAchievement':{if(reject())break;const origin=from?.getBoundingClientRect(),before=state.kk;if(window.classicAchievements.claim(param,state,fx(),D)){refresh();window.classicProgressFeel?.reward(origin,state.kk-before);}break;}
 case'Quantity':{let [which,n]=param.split(':');if(n==='cycle'){const qs=['1','10','100','Max'];n=qs[(qs.indexOf(state.quantities[which])+1)%4];}state.quantities[which]=n;refresh();break;}
 case'BuyLevels':{const i=Number(param),which=i===-1?'tap':'products',q=levelQuote(i);if(reject()||!q.affordable||funds()===0||state.levelBought.has(i))break;if(state.levels[0]===0&&i===0&&state.fixture!=='new'){state.levelBought.add(i);state.levels[0]=q.afterLevel;state.stockedQuote=q;renderPanels();setTab('Home');notice('Your first Phuljhari is on the shelf. Sales have begun.');motion.success($('display-'+D.products[0].id).querySelector('.product-art'),'celebrate');window.classicProgressFeel?.levels(0,0,state.levels[0]);break;}if(state.fixture==='new'&&i===0){reset('opened');setTab('Home');notice('Your first Phuljhari is on the shelf. Sales have begun.');motion.success($('display-'+D.products[0].id).querySelector('.product-art'),'celebrate');window.classicProgressFeel?.levels(0,0,state.levels[0]);break;}state.levelBought.add(i);if(i>=0)state.levels[i]=q.afterLevel;refresh();notice((i===-1?'Training':D.products[i].name)+' upgraded.');motion.success(i===-1?state.stack.at(-1)?.el.querySelector('.detail-hero'):$('scroll-Products').querySelectorAll('.product-image-frame')[i]);if(i>=0)motion.pulse($('display-'+D.products[i].id).querySelector('.product-art'));window.classicProgressFeel?.levels(i,q.beforeLevel,q.afterLevel);break;}
 case'BuyUpgrade':if(reject()||owned(param))break;{const u=D.upgrades.find(x=>x.id===param);if(!eligible(u)||fx().upgrades[param].price.value>funds())break;state.bought.add(param);if(state.pin===param)state.pin='';refresh();notice(u.name+' purchased.');motion.success(state.stack.at(-1)?.el.querySelector('.modal-head')||$('panel-Player').querySelector('.section-label'));}break;
 case'Filter':if(param==='category'){const a=['All','Products','Tapping','Skills','Shop'];state.category=a[(a.indexOf(state.category)+1)%a.length];state.target='all';}else if(param==='view'){const a=['Available','Upcoming','Owned','Full'];state.view=a[(a.indexOf(state.view)+1)%a.length];}else if(param==='clear-target')state.target='all';state.page=0;renderSheet();break;
 case'CataloguePage':state.page+=param==='next'?1:-1;renderSheet();state.stack.at(-1).el.querySelector('.modal-body').scrollTop=0;break;
 case'ReviewBatch':if(param==='refresh'&&state.condition==='stale'){state.condition='normal';$('review-condition').value='normal';}reviewBatch();break;
 case'BuyAllUpgrades':{if(reject()||funds()===0)break;const ids=fx().batches.All.ids.filter(id=>!owned(id));if(!ids.length)break;ids.forEach(id=>state.bought.add(id));if(ids.includes(state.pin))state.pin='';refresh();notice(ids.length+' upgrades purchased.');motion.success($('panel-Player').querySelector('.section-label'),'celebrate');break;}
 case'ConfirmBatch':if(reject()||state.condition==='stale'||!state.batch?.ids.length)break;state.batch.ids.forEach(id=>state.bought.add(id));close();refresh();notice('Your reviewed upgrades are purchased.');motion.success(state.stack.at(-1)?.el.querySelector('.modal-head')||$('panel-Player').querySelector('.section-label'),'celebrate');break;
 case'Pin':state.pin=param;renderPanels();renderSheet();notice('Pinned to Home');break;
 case'ActivateSkill':if(reject()||skillState(Number(param))!=='ready')break;{const i=Number(param),s=fx().skills[i],now=performance.now();state.skillTimers[i]={startedAt:now,activeUntil:now+(i===2?0:s.duration*1000),readyAt:now+s.cooldown*1000};state.skillStates[i]=skillState(i);}refresh();notice(skillNames[Number(param)]+' activated.');window.classicProgressFeel?.skill(Number(param));motion.success(state.stack.at(-1)?.el.querySelector('.detail-hero,.skill-hero-art')||state.stack.at(-1)?.el.querySelector('.modal-head')||$('scroll-Home').querySelectorAll('.classic-skill')[Number(param)],'rare');break;
 case'Draw':{const count=Number(param);if(![1,5].includes(count)||reject()||locked()||state.reveal)break;const cost=pullCost(count);if(state.credits<cost.credits||state.kk<cost.kk)break;state.credits-=cost.credits;state.kk-=cost.kk;const results=[];for(let n=0;n<count;n++){const ci=[0,1,18,27][state.drawIndex++%4],before=state.cardLevels[ci];state.cardLevels[ci]++;results.push({card:ci,before,after:before+1});}state.reveal={...results[0],results,index:0};renderPanels();open('DrawReveal',from);}break;
 case'Reveal':if(param==='continue'){if(!state.stack.at(-1)?.el.classList.contains('flip-settled')){settleCardFlip();break;}const r=state.reveal;if(r?.results&&r.index+1<r.results.length){r.index++;Object.assign(r,r.results[r.index]);renderSheet();}else{state.reveal=null;close();renderPanels();setTab('Legacy');}}break;
 case'Prestige':if(reject()||!fx().prestige.Eligible||state.condition==='stale')break;reset('rebuilt');setTab('Home');notice('Your shop is ready for a fresh start. Fame and Talent stay with you.');window.classicProgressFeel?.prestige();break;
 case'OfflineAd':if(state.stack.at(-1)?.name!=='Offline'||state.offlineDoubled||state.offlineAd==='watching'||offlineBase()<=0||reject())break;state.offlineAd='watching';renderSheet();notice('Rewarded ad preview: choose delivered to complete, or cancelled / failed / unavailable to test no-bonus outcomes.');break;
 case'Offline':if(state.stack.at(-1)?.name!=='Offline')break;close();break;
 case'Setting':state.settings[param]=!state.settings[param];if(from?.matches('[role="switch"]')){from.setAttribute('aria-checked',String(state.settings[param]));from.querySelector('.setting-switch-state').textContent=state.settings[param]?'ON':'OFF';$('app').dataset.reducedMotion=String(state.settings.motion);$('app').dataset.sound=String(state.settings.sound);$('app').dataset.music=String(state.settings.music);window.classicAudio?.configure({sound:state.settings.sound,music:state.settings.music});if(state.settings.sound)window.classicAudio?.play('click');motion.sync();}else refresh();break;
 case'Rename':{const value=$('shop-name').value.trim();if(!value){const input=$('shop-name');input.setAttribute('aria-invalid','true');$('shop-name-error').hidden=false;input.focus();notice('Enter a shop name first.');break;}state.name=value;close();refresh();notice('Shop name updated.');break;}
 case'Purchase':state.pack=Number(param);state.purchaseId='preview-purchase-'+(++purchaseSequence);open('Purchase',from);break;
 case'PurchaseResult':purchaseResult(param);break;
 case'Odds':open('Odds',from);break;
 case'Exact':if(param==='upgrade')state.exact=exact(fx().upgrades[state.upgrade].price);else if(param==='card')state.exact=esc(fx().cards[state.card].delta)+'<br>Current factor: '+esc(fx().cards[state.card].current.exact)+'<br>Next factor: '+esc(fx().cards[state.card].next.exact);else{const i=state.stack.at(-1)?.name==='TapTraining'?-1:state.product;state.exact=exact(levelQuote(i).cost);}open('Exact',from);break;

 case'Recovery':if(param==='fresh'){reset('new');setTab('Home');notice('Your fresh guest shop is ready.');}else if(param==='exit'){closeAll();open('RecoveryExit');}else if(['failed','save-error','unavailable'].includes(state.condition))notice('Still unable to load your save. Your existing progress is safe. Try again.');else{closeAll();setTab('Home');notice('Your saved shop is ready.');}break;
 }}
function purchaseResult(result){if(result==='retry'){if(state.pendingPack!==null){state.pack=state.pendingPack;open('Purchase');}else{state.condition='normal';$('review-condition').value='normal';state.purchaseStatus='';renderPanels();}return;}if(result==='delivered'&&state.condition==='save-error'){notice('Could not save delivery. The purchase remains pending.');state.purchaseStatus='pending';state.pendingPack=state.pack;return;}if(result==='delivered'){const key=state.purchaseId||(state.purchaseId='preview-purchase-'+(++purchaseSequence));if(!state.appliedPacks.has(key)){state.kk+=D.packs[state.pack].kajuKatli;state.appliedPacks.add(key);}state.pendingPack=null;}else if(result==='pending')state.pendingPack=state.pack;state.purchaseStatus=result;closeAll();setTab('Shop');renderPanels();notice(result==='delivered'?'Your Kaju Katli has arrived.':'Purchase '+result+' · no KK added');if(result==='delivered')motion.success($('panel-Shop').querySelector('.shop-balance'),'celebrate');}
function reset(name=state.fixture,previewResources=true){recentTapEarnings=[];closeAll();state.fixture=F[name]?name:'progressed';state.stockedQuote=null;state.offlineAd='idle';state.offlineDoubled=false;const f=fx();state.levels=[...f.levels];state.cardLevels=f.cards.map(c=>Number(c.level));state.credits=Number(f.credits);state.kk=Number(f.kk);window.classicAchievements.reset(state);if(previewResources&&Q.get('previewResources')==='pulls'){state.credits=Math.max(state.credits,4);state.kk=Math.max(state.kk,400);}state.bought.clear();state.levelBought.clear();state.appliedPacks.clear();state.pendingPack=null;state.purchaseStatus='';state.reveal=null;state.pin='';state.batch=null;state.quantities={products:'Max',tap:'Max'};state.skillStates=['ready','ready','ready'];state.skillTimers=[null,null,null];state.events=[];state.learned=new Set();state.drawIndex=0;state.category='All';state.target='all';state.search='';state.page=0;state.view='Available';$('review-fixture').value=state.fixture;renderPanels();}
function scale(){
 const capture=Q.has('capture'),device=/^\d+x\d+$/.test(Q.get('viewport')||'');
 const width=device?innerWidth:innerWidth<=800||capture?Math.min(innerWidth,480):Math.min(440,innerHeight*.54);
 const factor=width/360,height=innerHeight/factor,style=document.documentElement.style;
 style.setProperty('--frame-width','360px');style.setProperty('--s','1');style.setProperty('--scale','1');
 style.setProperty('--viewport-scale',factor);style.setProperty('--logical-height',height+'px');
 const world=Math.max(220,Math.min(470,height*(height<600?.5:.51)));
 $('app').style.setProperty('--native-world-height',world+'px');
 $('app').dataset.nativeCompact=String(height-world<230);
 requestAnimationFrame(updateScrollCues);
}
// Preserve the original layered stall, with independently accessible products.
D.products.forEach((p,i)=>{const old=$('display-'+p.id),button=document.createElement('button');for(const a of old.attributes)button.setAttribute(a.name,a.value);button.type='button';button.dataset.action='Navigate';button.dataset.param='ProductDetail:'+i;button.setAttribute('aria-label','View '+p.name);button.innerHTML='<span class="shelf-visual">'+old.innerHTML+'</span>';button.querySelector('.product-art').innerHTML=art(i);old.replaceWith(button);});
const sign=document.querySelector('.shop-title');sign.removeAttribute('aria-hidden');sign.setAttribute('role','img');
document.addEventListener('click',e=>{const top=state.stack.at(-1);if(top&&!top.el.querySelector('.modal-card').contains(e.target)){e.preventDefault();e.stopPropagation();close();return;}const el=e.target.closest('[data-action]');if(!el||el.disabled||el.closest('[inert]')||el.dataset.action==='Tap')return;handle(el.dataset.action,el.dataset.param||'',el);});
document.addEventListener('input',e=>{if(e.target.id==='catalogue-search'){state.search=e.target.value;state.page=0;scope='catalogue';serial=0;$('catalogue-results').innerHTML=catalogueResults();syncContract();requestAnimationFrame(updateScrollCues);}});
document.addEventListener('change',e=>{if(!e.target.id.startsWith('catalogue-'))return;const key=e.target.id.slice(10);if(['category','view','target'].includes(key)){state[key]=e.target.value;state.page=0;if(key==='category')state.target='all';renderSheet();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('review-open')){document.body.classList.remove('review-open');return;}if(state.stack.length)close();else setTab('Home');e.preventDefault();}if(e.key==='Tab'&&state.stack.length){const el=state.stack.at(-1).el,a=[...el.querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')].filter(x=>!x.closest('[hidden]'));if(!a.length){e.preventDefault();el.querySelector('.modal-card')?.focus();return;}if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus();}}});
let pointer=null;const tap=$('stall-tap');function doTap(point){if(state.stack.length||blocked())return;log('Tap','counter');recentTapEarnings.push({at:performance.now(),value:homeTap().value});updateTotalEarnings();motion.tap(point?{isConnected:true,getBoundingClientRect:()=>({left:point.clientX,top:point.clientY,width:1,height:1})}:document.querySelector('.world .tap-hint'),cash(homeTap()));}
tap.addEventListener('pointerdown',e=>{if(e.button===0)pointer={id:e.pointerId,x:e.clientX,y:e.clientY,drag:false};});tap.addEventListener('pointermove',e=>{if(pointer&&Math.hypot(pointer.x-e.clientX,pointer.y-e.clientY)>6*window.classicViewport.scale())pointer.drag=true;});tap.addEventListener('pointercancel',()=>pointer=null);tap.addEventListener('pointerup',e=>{if(pointer?.id===e.pointerId&&!pointer.drag)doTap(e);pointer=null;});tap.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();doTap();}});
$('review-screen').addEventListener('change',e=>{const route=e.target.value;closeAll();if(!tabs.includes(route))setTab(route==='Talent'||route==='Prestige'?'Legacy':route==='Purchase'?'Shop':'Home');navigate(route);document.body.classList.remove('review-open');});
$('review-fixture').addEventListener('change',e=>{const n=state.stack.at(-1)?.name||state.tab;reset(e.target.value);navigate(n);});$('review-condition').addEventListener('change',e=>{state.condition=e.target.value;offlineAdOutcome();refresh();});$('review-reset').addEventListener('click',()=>{const n=state.tab;reset();setTab(n);notice('Snapshot reset. All real game data is unchanged.');});$('mobile-review').addEventListener('click',()=>document.body.classList.toggle('review-open'));addEventListener('resize',scale);document.addEventListener('scroll',updateScrollCues,true);document.addEventListener('input',e=>{if(e.target.id==='shop-name'){e.target.removeAttribute('aria-invalid');$('shop-name-error').hidden=true;}});
document.addEventListener('classic-motion-change',()=>{if(!motion.enabled())settleCardFlip();});
if(Q.has('capture'))document.body.classList.add('capture');scale();reset(state.fixture);$('review-condition').value=state.condition;navigate(Q.get('screen')||'Home');
setInterval(()=>{tickSkills();updateTotalEarnings();},100);
document.addEventListener('visibilitychange',()=>{if(document.hidden){recentTapEarnings=[];updateTotalEarnings();}});
window.classicPreview={state,navigate,reset,condition(value){state.condition=value;$('review-condition').value=value;offlineAdOutcome();refresh();},getSnapshot:()=>({tab:state.tab,sheets:state.stack.map(x=>x.name),events:[...state.events],fixture:state.fixture,kk:state.kk,credits:state.credits})};
